WITH mgmtMenuListPage AS( SELECT * FROM ( SELECT * FROM ( SELECT A.* ,ROWNUM AS RNUM FROM( SELECT COUNT(*) OVER() total_count ,MENU_SEQ ,MENU_ID ,MENU_NM ,MENU_NM_ENG ,MENU_DESC ,MENU_ICON ,PARENT_ID ,TO_NUMBER(SORT_ORDER) AS SORT_ORDER ,URL ,USE_FLAG ,POPUP_FLAG ,CREATE_USER ,CREATE_DATE ,MODIFY_USER ,MODIFY_DATE FROM TB_M_MENUCFG WHERE 1=1
AND PARENT_ID IS NULL
AND PARENT_ID = #{sel_parentId}
AND MENU_SEQ IN ( SELECT MENU_SEQ FROM TB_M_MENU_SUBSCRIBE WHERE USER_ID IN ( SELECT USER_ID FROM TB_M_USERINFO WHERE USE_YN = 'Y' AND USER_ID = #{sel_user} OR USER_NM = #{sel_user}))
AND MENU_NM = #{sel_menuName}
AND USE_FLAG = #{sel_useYn}
ORDER BY SORT_ORDER ) A ) WHERE RNUM <= ${totalPagesize} ) WHERE RNUM > ${currentPageSize} ) SELECT * FROM mgmtMenuListPage

  		SELECT count(*) FROM TB_M_MENUCFG
		WHERE MENU_ID =	#{in_menuId}
		
		AND MENU_SEQ != #{in_menuSeq}

SELECT (CASE WHEN MAX(TO_NUMBER(SORT_ORDER)) > 0 THEN MAX(TO_NUMBER(SORT_ORDER)) ELSE TO_NUMBER(0) END) + 1 AS MENU_SEQ FROM TB_M_MENUCFG WHERE 1=1
AND PARENT_ID IS NULL
AND PARENT_ID = #{in_parentId}

